222: function blip(freq, dur, type = 'sine', vol = 0.18, slide = 0, delay = 0) {
223:   if (!AC || profile.muted) return;
224:   const t0 = AC.currentTime + delay;
225:   const o = AC.createOscillator(), gn = AC.createGain();
226:   o.type = type;
227:   o.frequency.setValueAtTime(freq, t0);
228:   if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(35, freq + slide), t0 + dur);
229:   gn.gain.setValueAtTime(0.0001, t0);
230:   gn.gain.exponentialRampToValueAtTime(vol, t0 + 0.006);
231:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
232:   o.connect(gn); gn.connect(masterGain);
233:   o.start(t0); o.stop(t0 + dur + 0.03);
234: }
235: function noiseBurst(dur, vol = 0.18, freq = 1100, delay = 0, type = 'bandpass', slideTo) {
236:   if (!AC || profile.muted || !noiseBuffer) return;
237:   const t0 = AC.currentTime + delay;
238:   const src = AC.createBufferSource();
239:   src.buffer = noiseBuffer;
240:   const f = AC.createBiquadFilter();
241:   f.type = type; f.frequency.setValueAtTime(freq, t0);
242:   if (slideTo) f.frequency.exponentialRampToValueAtTime(slideTo, t0 + dur);
243:   const gn = AC.createGain();
244:   gn.gain.setValueAtTime(vol, t0);
245:   gn.gain.exponentialRampToValueAtTime(0.0001, t0 + dur);
246:   src.connect(f); f.connect(gn); gn.connect(masterGain);
247:   src.start(t0); src.stop(t0 + dur + 0.02);
248: }
