338:   isTouch = window.matchMedia('(pointer: coarse)').matches;
339:   document.body.classList.toggle('touch', isTouch);
340:   S = clamp(Math.sqrt(W * H) / 860, 0.66, 1.3);
341:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
342:   arenaTop = isTouch ? 78 : 96;
343:   floorY = H - apron;
344:   const margin = isTouch ? 14 : 24;
345:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
