352:   skyGrad.addColorStop(1, '#ffe29a');
353:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
354:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
355:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
356:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
