358:   rebuildDecor();
359:   if (prevW && (prevW !== W || prevH !== H)) {
360:     const sx = W / prevW;
361:     const sy = H / prevFloor;
362:     for (const p of players) {
363:       p.x *= sx;
364:       p.y = prevFloor ? p.y * sy : floorY;
365:       p.y = Math.min(p.y, floorY);
366:     }
367:     for (const b of balls) { b.x *= sx; b.y *= sy; }
368:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
369:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
370:   }
371: }
