375: function drawPlayer(p, t) {
376:   const opp = getOpponent(p);
377:   const color = playerColor(p);
378:   const lookX = opp ? clamp((opp.x - p.x) / (260 * S), -1, 1) * p.facing : 0;
379:   const lookY = opp ? clamp(((opp.y - 42 * S) - (p.y - 52 * S)) / (260 * S), -1, 1) : 0;
380:   const aimSign = opp ? (Math.sign(opp.x - p.x) || 1) : p.facing;
381: 
382:   if ((p.onGround || p.ko) && state !== 'title') {
383:     ctx.beginPath();
384:     ctx.ellipse(p.x, p.y + 2 * S, 26 * S, 6 * S, 0, 0, TAU);
385:     ctx.fillStyle = 'rgba(36,19,53,.22)';
386:     ctx.fill();
387:   }
388: 
389:   ctx.save();
390:   ctx.translate(p.x, p.y);
391:   if (p.invuln > 0 && state === 'play' && Math.floor(p.invuln * 22) % 2 === 0) ctx.globalAlpha = 0.55;
392:   if (p.ko) {
393:     const k = clamp(p.koT / 0.9, 0, 1);
394:     ctx.rotate(k * Math.PI * 0.48 * (p.koDir || 1));
395:   }
396:   drawCharacter(ctx, p.char, {
397:     scale: S,
398:     facing: p.facing,
399:     t, phase: p.runPhase, run: p.onGround ? clamp(Math.abs(p.vx) / (runSpeedFor() || 1), 0, 1) : 0.4,
400:     onGround: p.onGround, vy: p.vy, seed: p.idx * 2.3,
401:     aiming: true, aim: aimSign * p.facing,
402:     charging: p.charging, charge: p.charge,
403:     throwAnim: p.throwAnim, catchAnim: p.catchAnim,
404:     hurt: p.hitstun, ko: p.ko,
405:     lookX, lookY,
406:     blink: p.blink > 0,
407:     color,
408:     showBall: !p.ko && p.throwAnim <= 0 && p.throwCd <= 0,
409:     ballRadius: 7.5 + p.charge * 7,
410:   });
411:   ctx.restore();
412: 
413:   // player ID badge above the head
414:   if (state !== 'title' && state !== 'matchEnd') {
415:     const bw = Math.max(15, 18 * S), bh = Math.max(11, 13 * S);
416:     const by = p.y - 104 * S;
417:     ctx.save();
418:     ctx.translate(p.x, by);
419:     rr(ctx, -bw / 2, -bh / 2, bw, bh, 7 * S);
420:     ctx.fillStyle = color;
421:     ctx.fill();
422:     ctx.lineWidth = 2.4 * S;
423:     ctx.strokeStyle = INK;
424:     ctx.stroke();
425:     ctx.beginPath();
426:     ctx.moveTo(-3.4 * S, bh / 2 - 1);
427:     ctx.lineTo(0, bh / 2 + 5 * S);
428:     ctx.lineTo(3.4 * S, bh / 2 - 1);
429:     ctx.closePath();
430:     ctx.fillStyle = color; ctx.fill();
431:     ctx.strokeStyle = INK; ctx.lineWidth = 2.2 * S; ctx.stroke();
432:     ctx.font = `${Math.max(8, 10 * S)}px Bungee, sans-serif`;
433:     ctx.textAlign = 'center';
434:     ctx.textBaseline = 'middle';
435:     ctx.fillStyle = p.idx === 0 ? INK : CREAM;
436:     ctx.fillText(String(p.idx + 1), 0, 0.6 * S);
437:     ctx.restore();
438:   }
439:   if (state === 'play' && !p.ko) {
440:     const b = nearbyCatchable(p);
441:     if (b && !p.charging) {
442:       const r = 66 * S + Math.sin(t * 8 + p.idx) * 3 * S;
443:       ctx.beginPath(); ctx.arc(p.x, p.y - 40 * S, r, 0, TAU);
444:       ctx.strokeStyle = withA(color, 0.5);
445:       ctx.lineWidth = 2.5 * S;
446:       ctx.setLineDash([5 * S, 6 * S]);
447:       ctx.stroke();
448:       ctx.setLineDash([]);
449:       ctx.font = `${9 * S}px Bungee, sans-serif`;
450:       ctx.textAlign = 'center';
451:       ctx.lineWidth = 3 * S;
452:       ctx.strokeStyle = 'rgba(36,19,53,.8)';
453:       ctx.strokeText('CATCH!', p.x, p.y + 24 * S);
454:       ctx.fillStyle = CREAM;
455:       ctx.fillText('CATCH!', p.x, p.y + 24 * S);
456:     }
457:   }
458: 
459:   // KO stars
460:   if (p.ko) {
461:     for (let i = 0; i < 3; i++) {
462:       const a = t * 3.4 + i * TAU / 3;
463:       const sx = p.x + Math.cos(a) * 22 * S;
464:       const sy = p.y - 82 * S + Math.sin(a) * 9 * S;
465:       ctx.save(); ctx.translate(sx, sy); ctx.rotate(a);
466:       starPath(ctx, 6 * S, 2.6 * S, 5);
467:       ctx.fillStyle = '#ffd23f'; ctx.fill();
468:       ctx.lineWidth = 1.6 * S; ctx.strokeStyle = INK; ctx.stroke();
469:       ctx.restore();
470:     }
471:   }
472: }
