539:     const cols = Math.max(1, Math.floor(b.w / (11 * S)));
540:     const rows = Math.max(1, Math.floor(b.h / (15 * S)));
541:     for (let r = 1; r < rows; r++) {
542:       for (let c = 0; c < cols; c++) {
543:         if (((r * 7 + c * 3 + Math.floor(b.seed)) % 5) !== 0) continue;
