328: function computeLayout() {
329:   const prevW = W, prevH = H, prevFloor = floorY;
330:   W = window.innerWidth;
331:   H = window.innerHeight;
332:   DPR = Math.min(window.devicePixelRatio || 1, 2);
333:   el.canvas.width = Math.round(W * DPR);
334:   el.canvas.height = Math.round(H * DPR);
335:   el.canvas.style.width = W + 'px';
336:   el.canvas.style.height = H + 'px';
337: 
338:   isTouch = window.matchMedia('(pointer: coarse)').matches;
339:   document.body.classList.toggle('touch', isTouch);
340:   const portraitBoost = H > W * 1.15 ? 1.26 : 1;
341:   S = clamp((Math.sqrt(W * H) / 860) * portraitBoost, 0.66, 1.35);
342:   apron = isTouch ? clamp(H * 0.27, 96, 134) : clamp(H * 0.075, 44, 66);
343:   arenaTop = isTouch ? 78 : 96;
344:   floorY = H - apron;
345:   const margin = isTouch ? 14 : 24;
346:   arena = { left: margin, right: W - margin, top: arenaTop, bottom: floorY };
347: 
348:   skyGrad = ctx.createLinearGradient(0, 0, 0, Math.max(200, floorY));
349:   skyGrad.addColorStop(0, '#3a1e66');
350:   skyGrad.addColorStop(0.38, '#8a3a8d');
351:   skyGrad.addColorStop(0.64, '#f56d73');
352:   skyGrad.addColorStop(0.85, '#ffb35e');
353:   skyGrad.addColorStop(1, '#ffe29a');
354:   vignetteGrad = ctx.createRadialGradient(W / 2, H * 0.45, Math.min(W, H) * 0.2, W / 2, H * 0.5, Math.max(W, H) * 0.78);
355:   vignetteGrad.addColorStop(0, 'rgba(20,8,35,0)');
356:   vignetteGrad.addColorStop(0.72, 'rgba(20,8,35,0.12)');
357:   vignetteGrad.addColorStop(1, 'rgba(20,8,35,0.55)');
358: 
359:   rebuildDecor();
360:   if (prevW && (prevW !== W || prevH !== H)) {
361:     const sx = W / prevW;
362:     const sy = prevFloor ? floorY / prevFloor : 1;
363:     for (const p of players) {
364:       p.x *= sx;
365:       p.y = prevFloor ? p.y * sy : floorY;
366:       p.y = Math.min(p.y, floorY);
367:     }
368:     for (const b of balls) { b.x *= sx; b.y *= sy; }
369:     for (const pk of pickups) { pk.x *= sx; pk.y = Math.min(pk.y * sy, floorY - 20); }
370:     if (state === 'title' || state === 'matchEnd') generatePlatforms();
371:   }
372: }
