374: function generatePlatforms() {
375:   const bw = arena.right - arena.left;
376:   const mirror = Math.random() < 0.5;
377:   const w = [
378:     clamp(250 * S, bw * 0.22, bw * 0.34),
379:     clamp(215 * S, bw * 0.20, bw * 0.30),
380:     clamp(185 * S, bw * 0.17, bw * 0.26),
381:   ];
382: 
383:   // Keep the lowest ledge above a brawler's head (plus badge) and keep every
384:   // step within a single jump. Short/landscape screens get fewer ledges rather
385:   // than a cramped stack that clips through the fighters.
386:   const step = 125 * S;
387:   const maxRise = Math.max(step, floorY - (arena.top + 54 * S));
388:   let levels = 1;
389:   if (maxRise >= step * 2) levels = 2;
390:   if (maxRise >= step * 3) levels = 3;
391: 
392:   // Chain the platforms horizontally so each one overlaps the next.
393:   const xs = [arena.left + bw * 0.05];
394:   for (let i = 1; i < levels; i++) {
395:     xs[i] = Math.min(xs[i - 1] + w[i - 1] - w[i] * 0.34, arena.right - w[i] - 10);
396:   }
397: 
398:   platforms = [];
399:   for (let i = 0; i < levels; i++) {
400:     platforms.push({
401:       x: xs[i],
402:       y: floorY - step * (i + 1),
403:       w: w[i],
404:       h: 12 * S,
405:       style: i,
406:     });
407:   }
408: 
409:   if (mirror) {
410:     for (const p of platforms) p.x = arena.left + (arena.right - p.x - p.w);
411:   }
412:   for (const p of platforms) {
413:     p.x = clamp(p.x, arena.left + 8, arena.right - p.w - 8);
414:     p.y = Math.max(p.y, arena.top + 54 * S);
415:   }
416: }
