475: function drawSky(t) {
476:   ctx.fillStyle = skyGrad;
477:   ctx.fillRect(0, 0, W, floorY);
478: 
479:   const sunX = W * 0.74, sunY = arena.top + (floorY - arena.top) * 0.22;
480:   const sunR = Math.min(W, H) * 0.072;
481:   ctx.save();
482:   ctx.translate(sunX, sunY);
483:   ctx.rotate(t * 0.018);
484:   ctx.fillStyle = 'rgba(255,236,168,.055)';
485:   for (let i = 0; i < 16; i++) {
486:     const a = i * TAU / 16;
487:     ctx.beginPath();
488:     ctx.moveTo(0, 0);
489:     ctx.arc(0, 0, Math.max(W, H) * 0.7, a, a + 0.1);
490:     ctx.closePath();
491:     ctx.fill();
492:   }
493:   ctx.restore();
494: 
495:   const glow = ctx.createRadialGradient(sunX, sunY, sunR * 0.2, sunX, sunY, sunR * 2.8);
496:   glow.addColorStop(0, 'rgba(255,239,177,.55)');
497:   glow.addColorStop(0.5, 'rgba(255,199,110,.16)');
498:   glow.addColorStop(1, 'rgba(255,160,90,0)');
499:   ctx.fillStyle = glow;
500:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR * 2.8, 0, TAU); ctx.fill();
501:   ctx.beginPath(); ctx.arc(sunX, sunY, sunR, 0, TAU);
502:   ctx.fillStyle = '#ffedb0'; ctx.fill();
503:   ctx.lineWidth = 3; ctx.strokeStyle = 'rgba(255,244,216,.55)'; ctx.stroke();
504: 
505:   // stars
506:   for (const st of stars) {
507:     const tw = 0.35 + 0.65 * (0.5 + 0.5 * Math.sin(t * st.sp + st.ph));
508:     ctx.beginPath(); ctx.arc(st.x, st.y, st.r, 0, TAU);
509:     ctx.fillStyle = `rgba(255,244,216,${tw * 0.65})`; ctx.fill();
510:   }
511: 
512:   // clouds
513:   ctx.fillStyle = 'rgba(255,220,190,.18)';
514:   for (const c of clouds) {
515:     const x = ((c.x + t * c.sp + 160) % (W + 320)) - 160;
516:     const y = c.y + Math.sin(t * 0.4 + c.ph) * 3;
517:     ctx.globalAlpha = c.a;
518:     ctx.beginPath();
519:     ctx.ellipse(x, y, 46 * c.s, 15 * c.s, 0, 0, TAU);
520:     ctx.ellipse(x + 34 * c.s, y - 8 * c.s, 30 * c.s, 17 * c.s, 0, 0, TAU);
521:     ctx.ellipse(x - 36 * c.s, y - 4 * c.s, 26 * c.s, 13 * c.s, 0, 0, TAU);
522:     ctx.fill();
523:     ctx.globalAlpha = 1;
524:   }
525: }
