  return 2100 * S * (roundMod.grav || 1);
}
function jumpSpeedFor() {
  return 790 * S * (roundMod.jump || 1) * (1 + 0.05 * upgradeBonus('jump'));
}
function ballGravityFor() {
  return 1650 * S * (roundMod.ballGrav || 1);
