111: function collideBallRect(b, pl) {
112:   const nx = clamp(b.x, pl.x, pl.x + pl.w);
113:   const ny = clamp(b.y, pl.y, pl.y + pl.h);
114:   const dx = b.x - nx, dy = b.y - ny;
115:   const d2 = dx * dx + dy * dy;
116:   if (d2 > b.r * b.r) return false;
117:   let nX, nY;
118:   const d = Math.sqrt(d2);
119:   if (d < 0.001) {
120:     const l = b.x - pl.x, r = pl.x + pl.w - b.x, t = b.y - pl.y, bo = pl.y + pl.h - b.y;
121:     const m = Math.min(l, r, t, bo);
122:     if (m === l) { nX = -1; nY = 0; b.x = pl.x - b.r; }
123:     else if (m === r) { nX = 1; nY = 0; b.x = pl.x + pl.w + b.r; }
124:     else if (m === t) { nX = 0; nY = -1; b.y = pl.y - b.r; }
125:     else { nX = 0; nY = 1; b.y = pl.y + pl.h + b.r; }
