#touch .pad{
  --btn:clamp(44px,5.6vh,56px);
  position:absolute;bottom:max(7px,env(safe-area-inset-bottom));
  pointer-events:none;
}
#touch .pad.p1{left:max(9px,env(safe-area-inset-left))}
#touch .pad.p2{right:max(9px,env(safe-area-inset-right))}
#touch .pad-buttons{
  display:grid;grid-template-columns:var(--btn) var(--btn) var(--btn);
  grid-template-rows:var(--btn) var(--btn);gap:6px;
}
.tbtn{
  pointer-events:auto;touch-action:none;appearance:none;
  border:2.5px solid var(--ink);border-radius:15px;background:rgba(255,244,216,.9);
  color:var(--ink);font-family:"Bungee",sans-serif;font-size:13px;line-height:1;
  box-shadow:0 4px 0 var(--ink),inset 0 -3px 0 rgba(0,0,0,.08);
  display:flex;align-items:center;justify-content:center;
  transition:transform .06s,background .06s;
}
.tbtn:active,.tbtn.pressed{transform:translateY(3px);box-shadow:0 1px 0 var(--ink);background:#fff}
#touch .pad.p1 .tbtn{background:rgba(206,250,255,.92)}
#touch .pad.p2 .tbtn{background:rgba(255,220,239,.92)}
.tbtn.move{font-size:16px;grid-row:2}
.tbtn.move[data-act="left"]{grid-column:1}
.tbtn.move[data-act="right"]{grid-column:2}
.tbtn.jump{grid-column:3;grid-row:1;background:var(--yellow)!important;font-size:11px}
.tbtn.throw{grid-column:3;grid-row:2;background:var(--coral)!important;color:var(--cream);font-size:10.5px;letter-spacing:.06em;text-shadow:0 2px 0 rgba(36,19,53,.35)}

/* ---------------- slider pads ---------------- */
#touch .pad-sliders{
  --sw:clamp(40px,5.2vh,50px);
  --sh:clamp(44px,5.6vh,56px);
  --track:clamp(64px,17vw,96px);
  display:none;
  grid-template-columns:var(--sw) var(--track) var(--sh);
  grid-template-rows:var(--sh) var(--sh);
  grid-template-areas:"aim jump throw" "aim move throw";
  gap:6px;
}
#touch .pad-sliders.p2{grid-template-areas:"throw jump aim" "throw move aim"}
body.ctrl-sliders #touch .pad-buttons{display:none}
body.ctrl-sliders #touch .pad-sliders{display:grid}
#touch .pad-sliders .tbtn.jump,
#touch .pad-sliders .tbtn.throw{grid-column:auto;grid-row:auto}
#touch .pad-sliders .tbtn.jump{grid-area:jump}
#touch .pad-sliders .tbtn.throw{grid-area:throw}
.slider{
  position:relative;pointer-events:auto;touch-action:none;overflow:hidden;
  border:2.5px solid var(--ink);border-radius:13px;
  background:rgba(255,244,216,.82);box-shadow:0 4px 0 var(--ink),inset 0 -3px 0 rgba(0,0,0,.08);
}
.slider.active{background:#fff}
.slider-track{
  position:absolute;left:8px;right:8px;top:50%;height:8px;margin-top:-4px;
  border-radius:99px;background:#d8c8a9;border:1.5px solid rgba(36,19,53,.5);overflow:hidden;
}
.slider-fill{position:absolute;left:0;top:0;bottom:0;width:calc(var(--v,.5) * 100%);background:var(--p1);opacity:.75}
.pad-sliders.p2 .slider-fill{background:var(--p2)}
.slider-thumb{
  position:absolute;width:20px;height:20px;border-radius:50%;background:var(--cream);
  border:2.5px solid var(--ink);box-shadow:0 2px 0 rgba(36,19,53,.35);
  left:calc(4px + var(--v,.5) * (100% - 28px));top:50%;margin-top:-10px;
  transition:transform .05s;
}
.slider.active .slider-thumb{transform:scale(1.12)}
.slider-cap{
  position:absolute;left:0;right:0;bottom:2px;text-align:center;
  font-family:"Bungee",sans-serif;font-size:7.5px;letter-spacing:.1em;color:#6b5880;
  pointer-events:none;
}
.slider.aim{grid-area:aim}
.slider.move{grid-area:move}
.slider.aim .slider-track{
  left:50%;right:auto;top:8px;bottom:8px;width:8px;height:auto;margin:0 0 0 -4px;
}
.slider.aim .slider-fill{
  top:auto;bottom:0;left:0;right:0;width:auto;height:calc((1 - var(--v,.55)) * 100%);
}
.slider.aim .slider-thumb{
  left:50%;top:calc(4px + var(--v,.55) * (100% - 28px));margin:-10px 0 0 -10px;
}
.slider.aim .slider-cap{bottom:3px}
.slider.move .slider-cap{bottom:2px}

